def insert_universities():
    conn = sqlite3.connect('/workspace/data/universities.db')
    cursor = conn.cursor()
    
    insert_query = """
    INSERT INTO university_programs (
        id, name, country, city, degree, program, program_category, language, duration_years, tuition_usd,
        cgpa_requirement, cgpa_scale, ielts_requirement, toefl_requirement, gre_requirement, gre_quant_min,
        research_required, research_preferred, research_experience_required, minimum_research_years,
        published_paper_required, published_paper_preferred, minimum_published_papers, journal_paper_preferred,
        conference_paper_preferred, first_author_preferred, indexed_publication_preferred, research_proposal_required,
        supervisor_contact_required, work_experience_years, scholarship_available, scholarship_details,
        application_deadline, intake_months, acceptance_rate, qs_ranking, work_permit_friendly,
        pr_friendliness_score, part_time_work_allowed, living_cost_monthly_usd, application_fee_usd,
        official_website, program_url, scholarship_url, source_url, official_logo_url, last_verified,
        data_confidence_score, notes
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """
    
    try:
        cursor.executemany(insert_query, new_universities)
        conn.commit()
        print(f"Successfully inserted {len(new_universities)} university records.")
        
        # Verify insertion
        cursor.execute('SELECT COUNT(*) FROM university_programs')
        total = cursor.fetchone()[0]
        print(f"Total records in database: {total}")
        
    except sqlite3.IntegrityError as e:
        print(f"Integrity error: {e}")
    except Exception as e:
        print(f"Error: {e}")
    finally:
        conn.close()

if __name__ == '__main__':
    insert_universities()
